        "NETT TOTAL", "NET TOTAL", "TOTAL AMT PAYABLE", "AMT PAYABLE",
        "TOTAL",
        "AMOUNT",
    ],
]

EXCLUSIONS = [
    "SUBTOTAL",
    "SUB TOTAL",
    "SUB-TOTAL",
    "DISCOUNT",
    "CHANGE",
    "CASH TENDERED",
]

# Substrings in a compressed (non-alphanumeric stripped) form that indicate
# a tax-related aggregation rather than the final total.
TAX_TOTAL_COMPRESSED = [
    "TOTALGST", "TOTALSST", "TOTALTAX", "TOTALVAT",
    "NETGST", "NETTGST", "NETSST", "NETTAX",
    "GSTTOTAL", "SSTTOTAL", "TAXTOTAL", "VATTOTAL",
    "GSTAMOUNT", "SSTAMOUNT", "TAXAMOUNT", "VATAMOUNT",
    "GSTAMT", "SSTAMT", "TAXAMT", "VATAMT",
]

# Column header words: the primary purpose of a receipt column header line.
COLUMN_HEADER_WORDS = {
    "QTY", "QUANTITY", "PRICE", "S/PRICE", "U/PRICE", "UPRICE",
    "UNIT", "ITEM", "DESCRIPTION", "DESC", "RSP", "TAX", "CODE",
}

# Numbers: `1,234.56`, `12.34`, or OCR comma-decimal like `12,34`.
NUMBER_RE = re.compile(
    r"(?<![\d\w])(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2}|\d+,\d{2})(?![\d])"
)

MONTHS = {
    "JAN": 1, "FEB": 2, "MAR": 3, "APR": 4, "MAY": 5, "JUN": 6,
    "JUL": 7, "AUG": 8, "SEP": 9, "SEPT": 9, "OCT": 10, "NOV": 11, "DEC": 12,
}

DATE_PATTERNS = [
    # DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY (year 4 digits)
    re.compile(r"(?<!\d)(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})(?!\d)"),
    # DD/MM/YY, DD-MM-YY, DD.MM.YY (year 2 digits)
    re.compile(r"(?<!\d)(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})(?!\d)"),
    # DD MMM YYYY / DD MMM YY
    re.compile(r"(?<!\d)(\d{1,2})[\s\-]+([A-Za-z]{3,9})[\s\-]+(\d{2,4})(?!\d)"),
]


def extract_last_number(line: str):
    matches = NUMBER_RE.findall(line)
    if not matches:
        return None
    raw = matches[-1]
    # Normalize European-style comma decimal (`12,34` -> `12.34`).
    if "." not in raw:
        raw = raw.replace(",", ".")
    else:
        raw = raw.replace(",", "")
    return raw


def _compressed(line: str) -> str:
    return re.sub(r"[^A-Z0-9]", "", line.upper())


def is_excluded(line: str) -> bool:
    upper = line.upper()
    if any(k in upper for k in EXCLUSIONS):
        return True
    compressed = _compressed(line)
    if any(tag in compressed for tag in TAX_TOTAL_COMPRESSED):
        return True
    return False


def looks_like_column_header(line: str) -> bool:
    """Treat lines containing multiple column-header tokens as column headers."""
    tokens = re.findall(r"[A-Za-z/]+", line.upper())
    hits = sum(1 for t in tokens if t in COLUMN_HEADER_WORDS)
    return hits >= 2


def truncate_summary(lines):
    """Drop lines starting at a *** Summary section (GST/SST/TAX summary tables)."""
    cut = len(lines)
    for i, line in enumerate(lines):
        c = _compressed(line)
        if "GSTSUMMARY" in c or "SSTSUMMARY" in c or "TAXSUMMARY" in c:
            cut = i
            break
    return lines[:cut]


def find_total(lines):
    """Return total amount string (e.g. '47.70') or None."""
    trimmed = truncate_summary(lines)
    for priority_keywords in PRIORITIES:
        matched = []
        for i, line in enumerate(trimmed):
            upper = line.upper()
            if not any(k in upper for k in priority_keywords):
                continue
            if is_excluded(line):
                continue
            if looks_like_column_header(line):
                continue
            matched.append(i)

        # Prefer the latest match (final total usually appears near the end).
        for i in reversed(matched):
            val = extract_last_number(trimmed[i])
            if val is not None:
                return val
            if i + 1 < len(trimmed):
                val = extract_last_number(trimmed[i + 1])
                if val is not None:
                    return val
    return None


def parse_date_components(day, month, year):
    try:
        day = int(day)
        if isinstance(month, str) and not month.isdigit():
            m_upper = month.upper()[:3]
            if m_upper not in MONTHS:
                return None
            month = MONTHS[m_upper]
        else:
            month = int(month)
        year = int(year)
        if year < 100:
            year += 2000
        if not (1 <= month <= 12):
            return None
        if not (1 <= day <= 31):
            return None
        if not (2000 <= year <= 2099):
            return None
        return f"{year:04d}-{month:02d}-{day:02d}"
    except (ValueError, TypeError):
        return None


def find_date(text, lines):
    """Prefer a date near a 'Date' keyword; fallback to first plausible date."""
    for i, line in enumerate(lines):
        if "DATE" in line.upper():
            for pat in DATE_PATTERNS:
                for m in pat.finditer(line):
                    iso = parse_date_components(*m.groups())
                    if iso:
                        return iso
            if i + 1 < len(lines):
                for pat in DATE_PATTERNS:
                    for m in pat.finditer(lines[i + 1]):
                        iso = parse_date_components(*m.groups())
                        if iso:
                            return iso

    for line in lines:
        for pat in DATE_PATTERNS:
            for m in pat.finditer(line):
                iso = parse_date_components(*m.groups())
                if iso:
                    return iso
    return None


def process_image(path):
    try:
        img = Image.open(path)
        text = pytesseract.image_to_string(img)
    except Exception as e:
        print(f"OCR failed for {path}: {e}", file=sys.stderr)
        return None, None
    lines = [l for l in text.splitlines() if l.strip()]
    date = find_date(text, lines)
    total = find_total(lines)
    return date, total


def main():
    files = sorted(os.listdir(IMG_DIR))
    files = [f for f in files if f.lower().endswith((".png", ".jpg", ".jpeg"))]

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])

    for fname in files:
        path = os.path.join(IMG_DIR, fname)
        date, total = process_image(path)
        print(f"{fname}: date={date}, total={total}")
        ws.append([fname, date, total])

    wb.save(OUT_PATH)
    print(f"Saved {OUT_PATH}")


if __name__ == "__main__":
    main()
